// Build summary after all students processed
const students = $('Get Eligible Students (Not Asked in 30 Days)').all();
const count = students.length;
if (count === 0) return [{ json: { skip: true } }];
return [{ json: { skip: false, count, summary: `⭐ Weekly Review Request Campaign

Sent to ${count} students today.

Students contacted this week will be checked next week for new reviews.

Check Google Business Profile in 3-4 days.` } }];
